 individually named cities. Generic city-count counter and promotional discounts not adopted. No owner contact, credential/insurance check, review validation, workmanship, availability or coating guarantee; no photos reused."},{"name":"JuJu Detail","city":"Stockton","address":"1156 School Ave, Stockton, CA 95205","phone":"(209) 561-8613","website":"https://www.jujudetail.com/","source_url":"https://www.jujudetail.com/locations/manteca-ca/","areas":["Mountain House","Tracy","Lathrop","Manteca"],"tags":["mobile auto detailing","interior auto detailing","exterior auto detailing"],"description":"Stockton provider advertising mobile auto detailing, interior cleaning and exterior/full-detail services. Its official Manteca page explicitly includes Lathrop and names Mountain House, Tracy and Manteca in its mobile coverage. The advertised Stockton shop address is for optional drop-off; confirm arrangements before visiting. Confirm address eligibility, vehicle needs, travel charges, quote and dates directly.","note":"First-party website information checked November 23, 2026: identity, public phone, advertised Stockton shop/drop-off address, mobile detailing services and explicitly named coverage cities. No inferred radius or free-travel promise. License/insurance claims, workmanship, prices, coating performance, ratings and current appointment availability not independently confirmed; no portfolio reused."}]'::jsonb) loop
if exists(select 1 from public.businesses where lower(rtrim(website,'/'))=lower(rtrim(r->>'website','/')) or right(regexp_replace(coalesce(phone,''),'[^0-9]','','g'),10)=right(regexp_replace(r->>'phone','[^0-9]','','g'),10) or lower(name)=lower(r->>'name')) then raise exception 'Duplicate candidate: %',r->>'name';end if;
insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,needs_review,source,source_url,verification_source,verified_at)values(r->>'name','Automotive',r->>'city',r->>'address',r->>'phone',r->>'website',r->>'description','approved',true,false,null,0,false,'editorial_first_party',r->>'source_url','first_party_website_desk_check',now())returning id into bid;
insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note)values(bid,r->>'source_url',array['identity','public phone','website','advertised services','explicit service cities','scope and limitations'],array(select jsonb_array_elements_text(r->'areas')),array(select jsonb_array_elements_text(r->'tags')),r->>'note');
select to_jsonb(b) into applied from public.businesses b where id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference)values(bid,'{}'::jsonb,applied||jsonb_build_object('service_areas',r->'areas','service_tags',r->'tags','scope_note',r->>'note'),'CORE-01 individually checked mobile detailing service expansion; no owner availability or quality endorsement',r->>'source_url');end loop;end $curate$;
